type OrderStatus = 'processing' | 'shipped' | 'delivered' | 'cancelled' | 'returned';
type PaymentOutcome = 'captured' | 'failed';
type Feature = 'express-shipping' | 'gift-wrap';

type CheckoutEvent = `order.${OrderStatus}` | `payment.${PaymentOutcome}`;
type FlagEnvVar = `CHECKOUT_${Uppercase<Feature>}`;
type PathParams<P extends string> =
  P extends `${string}:${infer Param}/${infer Rest}`
    ? Param | PathParams<Rest>
    : P extends `${string}:${infer Param}`
      ? Param
      : never;

function buildPath<P extends string>(pattern: P, params: Record<PathParams<P>, string | number>): string {
  // Every :param in the pattern has a key in params, by construction.
  const values = params as Record<string, string | number>;
  return pattern.replace(/:(\w+)/g, (_, name: string) => encodeURIComponent(String(values[name])));
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<CheckoutEvent,
  | 'order.processing' | 'order.shipped' | 'order.delivered' | 'order.cancelled' | 'order.returned'
  | 'payment.captured' | 'payment.failed'>>;
type T2 = Expect<Equal<FlagEnvVar, 'CHECKOUT_EXPRESS-SHIPPING' | 'CHECKOUT_GIFT-WRAP'>>;
type T3 = Expect<Equal<PathParams<'/orders/:orderId/lines/:lineId'>, 'orderId' | 'lineId'>>;
type T4 = Expect<Equal<PathParams<'/customers/:customerId'>, 'customerId'>>;
type T5 = Expect<Equal<PathParams<'/orders'>, never>>;

// @ts-expect-error: 'order.shiped' is a typo
const typo: CheckoutEvent = 'order.shiped';

// @ts-expect-error: lineId is missing
buildPath('/orders/:orderId/lines/:lineId', { orderId: 1042 });

console.log(buildPath('/orders/:orderId/lines/:lineId', { orderId: 1042, lineId: 3 }));
